import type { CardMotif } from "@/data/projects";

/*
 * Per-project configuration for the dossier's manga backdrop (components/project-dossier-manga.tsx,
 * docs/project-dossier-manga.md). Everything that is the same for every project (panel geometry,
 * palette, gradients, scale, motion, responsive rules) lives in the component and its CSS module.
 * A preset only says which two plates to show and where each plate's subject sits.
 *
 * The plates are lavender-gray screentone renderings of crops from the five owner-authorized tarot
 * illustrations, generated by scripts/build-dossier-manga-plates.mjs into public/images/dossier-manga/.
 */

export type MangaPlate = {
  src: string;
  /** CSS object-position: keeps the plate's subject in frame when the panel crops it. */
  focus: string;
};

export type DossierMangaPreset = {
  /** The figure, read from the top-right corner of the dossier. */
  upper: MangaPlate;
  /** A detail (hands, props, companion), read from the bottom-right corner. */
  lower: MangaPlate;
  /**
   * Where the upper panel's focus lines converge, as [x, y] in percent of the upper panel's box. Set
   * on the figure's face so the lines frame it rather than cross it.
   */
  focusPoint: readonly [number, number];
};

const plate = (slug: string, kind: "upper" | "lower", focus: string): MangaPlate => ({
  src: `/images/dossier-manga/${slug}-${kind}.webp`,
  focus,
});

export const DOSSIER_MANGA_PRESETS: Record<CardMotif, DossierMangaPreset> = {
  // The Fool / SpeakLab AI: the gentleman in the top hat (mirrored); his cape and waistcoat below.
  threshold: {
    upper: plate("speaklab-ai", "upper", "70% 35%"),
    lower: plate("speaklab-ai", "lower", "40% 50%"),
    focusPoint: [72, 34],
  },
  // The World / Autonomous Delivery Rover: the sleeper among mushrooms (mirrored); his folded hands below.
  orbit: {
    upper: plate("autonomous-delivery-rover", "upper", "70% 40%"),
    lower: plate("autonomous-delivery-rover", "lower", "50% 60%"),
    focusPoint: [72, 38],
  },
  // The Magician / Guiding Hands: the conjurer's face under the hat brim; her hands and pen below.
  spark: {
    upper: plate("guiding-hands", "upper", "64% 30%"),
    lower: plate("guiding-hands", "lower", "36% 40%"),
    focusPoint: [52, 28],
  },
  // Justice / Road Report: the woman with the umbrella; the golden retriever below.
  balance: {
    upper: plate("road-report", "upper", "70% 18%"),
    lower: plate("road-report", "lower", "26% 55%"),
    focusPoint: [62, 17],
  },
  // The Star / ZBXP: the writer at the lamp; the typewriter and gloved hands below.
  star: {
    upper: plate("zbxp", "upper", "70% 40%"),
    lower: plate("zbxp", "lower", "40% 55%"),
    focusPoint: [68, 40],
  },
};
